#include <iostream>
#include <memory>

struct Node {
    int data;
    Node* next{nullptr};
    Node* prev{nullptr};
    explicit Node(int val) : data(val) {}
};

class SimpleDoublyList {
private:
    Node* firstPtr{nullptr};
    Node* lastPtr{nullptr};

public:
    SimpleDoublyList() = default;
    ~SimpleDoublyList() {
        Node* current = firstPtr;
        while (current != nullptr) {
            Node* nextNode = current->next;
            delete current;
            current = nextNode;
        }
    }

    void insertBack(int val) {
        Node* newNode = new Node(val);
        if (!firstPtr) {
            firstPtr = lastPtr = newNode;
        } else {
            lastPtr->next = newNode;
            newNode->prev = lastPtr;
            lastPtr = newNode;
        }
    }

    void printForward() const {
        std::cout << "Forward: ";
        for (Node* curr = firstPtr; curr != nullptr; curr = curr->next) {
            std::cout << curr->data << " ";
        }
        std::cout << "\n";
    }

    void printBackward() const {
        std::cout << "Backward: ";
        for (Node* curr = lastPtr; curr != nullptr; curr = curr->prev) {
            std::cout << curr->data << " ";
        }
        std::cout << "\n";
    }
};

int main() {
    SimpleDoublyList list;
    list.insertBack(12);
    list.insertBack(7);
    list.insertBack(11);
    list.insertBack(5);

    list.printForward();
    list.printBackward();
    return 0;
}

#include <iostream>

template<typename T>
class SimpleList {
private:
    struct ListNode {
        T data;
        ListNode* nextPtr;
        ListNode(const T& val, ListNode* next = nullptr) : data(val), nextPtr(next) {}
    };
    ListNode* firstPtr{nullptr};

public:
    SimpleList() = default;
    ~SimpleList() {
        while (firstPtr) {
            ListNode* temp = firstPtr;
            firstPtr = firstPtr->nextPtr;
            delete temp;
        }
    }

    void insertAtFront(const T& val) {
        firstPtr = new ListNode(val, firstPtr);
    }

    bool removeFromFront(T& val) {
        if (isEmpty()) return false;
        ListNode* temp = firstPtr;
        val = temp->data;
        firstPtr = firstPtr->nextPtr;
        delete temp;
        return true;
    }

    bool isEmpty() const {
        return firstPtr == nullptr;
    }

    void print() const {
        if (isEmpty()) {
            std::cout << "The list is empty\n";
            return;
        }
        std::cout << "The list is:";
        for (ListNode* curr = firstPtr; curr != nullptr; curr = curr->nextPtr) {
            std::cout << " " << curr->data;
        }
        std::cout << "\n";
    }
};

template<typename STACKTYPE>
class Stack : private SimpleList<STACKTYPE> {
public:
    void push(const STACKTYPE& data) {
        this->insertAtFront(data);
    }

    bool pop(STACKTYPE& data) {
        return this->removeFromFront(data);
    }

    bool isStackEmpty() const {
        return this->isEmpty(); // 'this->' is required for dependent name resolution
    }

    void printStack() const {
        this->print();
    }
};

int main() {
    Stack<int> intStack;
    std::cout << "processing an integer Stack\n";
    for (int i = 0; i < 3; ++i) {
        intStack.push(i);
        intStack.printStack();
    }

    int val;
    while (!intStack.isStackEmpty()) {
        intStack.pop(val);
        std::cout << val << " popped from stack\n";
        intStack.printStack();
    }
    return 0;
}
